const raw=$json.text??$json.output??$json.response??'';
let d;
try {
  const clean=String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim();
  d=JSON.parse(clean);
} catch(error) {
  return [{json:{status:'error',worker:'RECLAMOS',respuesta:'No pude validar el reclamo con evidencia estructurada. Una persona continuará la atención.',requires_human:true,evidence:[]}}];
}
function isError(value) {
  if(value&&typeof value==='object'&&!Array.isArray(value)&&(value.error||value.success===false)) return true;
  const text=typeof value==='string'?value:JSON.stringify(value??'');
  return /^\s*(error|failed|failure)\b/i.test(text)||/\b(no output data|no rows returned)\b/i.test(text);
}
function isRow(value) {
  if(!value||typeof value!=='object'||Array.isArray(value)||!Object.keys(value).length||isError(value)) return false;
  return Object.keys(value).some(key=>!['success','message'].includes(key.toLowerCase()));
}
function rowsFromObservation(observation,depth=0) {
  if(depth>6||observation==null||isError(observation)) return [];
  let value=observation;
  if(typeof value==='string') {
    try { value=JSON.parse(value); } catch { return []; }
  }
  if(Array.isArray(value)) return value.flatMap(item=>rowsFromObservation(item,depth+1));
  if(!value||typeof value!=='object') return [];
  const keys=Object.keys(value);
  if(keys.length===1&&['response','output','json'].includes(keys[0])) return rowsFromObservation(value[keys[0]],depth+1);
  for(const key of ['data','results','rows']) {
    if(keys.length<=2&&value[key]!==undefined) return rowsFromObservation(value[key],depth+1);
  }
  return isRow(value)?[value]:[];
}
function quoteObservation(value) {
  if(value==null||isError(value)) return '';
  const quote=typeof value==='string'?value.trim():JSON.stringify(value);
  return quote&&quote!=='{}'&&quote!=='[]'?quote:'';
}
const evidence=[];
for(const step of Array.isArray($json.intermediateSteps)?$json.intermediateSteps:[]) {
  const tool=String(step?.action?.tool??'');
  if(tool==='Registrar_Reclamo_Google_Sheets') {
    const quote=quoteObservation(step.observation);
    if(quote) evidence.push({source:tool,quote});
  } else if(tool==='Cosulta_Estado_Reclamo_Google_Sheets'||tool==='Actualizar/Cancelar_Reclamo_Google_Sheets') {
    for(const row of rowsFromObservation(step.observation)) evidence.push({source:tool,quote:JSON.stringify(row)});
  }
}
const hasEvidence=evidence.length>0;
const hasWriteEvidence=evidence.some(item=>item.source==='Registrar_Reclamo_Google_Sheets');
const response=String(d.respuesta??'');
const normalizedResponse=response.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const claimsRegistration=/\b(tu reclamo (?:ha quedado|quedo|fue|esta) registrado|he registrado (?:el )?reclamo|registre (?:el )?reclamo)\b/.test(normalizedResponse);
const unsupportedRegistration=claimsRegistration&&!hasWriteEvidence;
return [{json:{status:hasEvidence&&!unsupportedRegistration?(d.status??'success'):'needs_human',worker:'RECLAMOS',respuesta:unsupportedRegistration?'No pude verificar el registro con el resultado de la herramienta. Una persona comprobará el caso antes de responder.':response,requires_human:Boolean(d.requires_human)||!hasEvidence||unsupportedRegistration,evidence,human_decision:String($('Start').first().json.human_decision??'')}}];
